From d15cddd903215d45a25471277db6e2fe79ef9db2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:21:20 +0100
Subject: [PATCH] applets/systemtray: load "Always shown" D-Bus activated
 applets

Applets like Media Player were only loaded while their D-Bus service was
running, so setting them to "Always shown" did nothing until a player
appeared. Now such applets are also loaded whenever they're always shown.

BUG: 444710
---
 applets/systemtray/dbusserviceobserver.cpp |  5 ++++
 applets/systemtray/dbusserviceobserver.h   |  1 +
 applets/systemtray/plasmoidregistry.cpp    | 32 ++++++++++++++++++++--
 applets/systemtray/plasmoidregistry.h      |  2 ++
 4 files changed, 37 insertions(+), 3 deletions(-)

diff --git a/applets/systemtray/dbusserviceobserver.cpp b/applets/systemtray/dbusserviceobserver.cpp
index 70f5058592..b249ca9f78 100644
--- a/applets/systemtray/dbusserviceobserver.cpp
+++ b/applets/systemtray/dbusserviceobserver.cpp
@@ -83,6 +83,11 @@ bool DBusServiceObserver::isDBusActivable(const QString &pluginId)
     return m_dbusActivatableTasks.contains(pluginId);
 }

+bool DBusServiceObserver::isServiceRunning(const QString &pluginId) const
+{
+    return m_dbusServiceCounts.value(pluginId) > 0;
+}
+
 /* Loading and unloading Plasmoids when dbus services come and go
  *
  * This works as follows:
diff --git a/applets/systemtray/dbusserviceobserver.h b/applets/systemtray/dbusserviceobserver.h
index 8a098b36d5..90cc4a25de 100644
--- a/applets/systemtray/dbusserviceobserver.h
+++ b/applets/systemtray/dbusserviceobserver.h
@@ -28,6 +28,7 @@ public:
     void registerPlugin(const KPluginMetaData &pluginMetaData);
     void unregisterPlugin(const QString &pluginId);
     bool isDBusActivable(const QString &pluginId);
+    bool isServiceRunning(const QString &pluginId) const;

 Q_SIGNALS:
     void serviceStarted(const QString &pluginId);
diff --git a/applets/systemtray/plasmoidregistry.cpp b/applets/systemtray/plasmoidregistry.cpp
index 89e7125449..20366df1a4 100644
--- a/applets/systemtray/plasmoidregistry.cpp
+++ b/applets/systemtray/plasmoidregistry.cpp
@@ -22,7 +22,11 @@ PlasmoidRegistry::PlasmoidRegistry(SystemTraySettings *settings, QObject *parent
     , m_dbusObserver(new DBusServiceObserver(settings, this))
 {
     connect(m_dbusObserver, &DBusServiceObserver::serviceStarted, this, &PlasmoidRegistry::plasmoidEnabled);
-    connect(m_dbusObserver, &DBusServiceObserver::serviceStopped, this, &PlasmoidRegistry::plasmoidStopped);
+    connect(m_dbusObserver, &DBusServiceObserver::serviceStopped, this, [this](const QString &pluginId) {
+        if (!m_shownItems.contains(pluginId)) {
+            Q_EMIT plasmoidStopped(pluginId);
+        }
+    });
 }

 void PlasmoidRegistry::init()
@@ -47,6 +51,8 @@ void PlasmoidRegistry::init()
                                           SLOT(packageUninstalled(QString)));

     connect(m_settings, &SystemTraySettings::enabledPluginsChanged, this, &PlasmoidRegistry::onEnabledPluginsChanged);
+    connect(m_settings, &SystemTraySettings::configurationChanged, this, &PlasmoidRegistry::onConfigurationChanged);
+    m_shownItems = m_settings->shownItems();

     for (const auto &info : Plasma::PluginLoader::self()->listAppletMetaData(QString())) {
         registerPlugin(info);
@@ -70,7 +76,7 @@ bool PlasmoidRegistry::isSystemTrayApplet(const QString &pluginId)
 void PlasmoidRegistry::onEnabledPluginsChanged(const QStringList &enabledPlugins, const QStringList &disabledPlugins)
 {
     for (const QString &pluginId : enabledPlugins) {
-        if (m_systrayApplets.contains(pluginId) && !m_dbusObserver->isDBusActivable(pluginId)) {
+        if (m_systrayApplets.contains(pluginId) && (!m_dbusObserver->isDBusActivable(pluginId) || m_shownItems.contains(pluginId))) {
             Q_EMIT plasmoidEnabled(pluginId);
         }
     }
@@ -81,6 +87,26 @@ void PlasmoidRegistry::onEnabledPluginsChanged(const QStringList &enabledPlugins
     }
 }

+void PlasmoidRegistry::onConfigurationChanged()
+{
+    // "Always shown" D-Bus activated plasmoids are loaded even when their service is not running
+    const QStringList shownItems = m_settings->shownItems();
+    const QStringList pluginIds = m_systrayApplets.keys();
+    for (const QString &pluginId : pluginIds) {
+        if (!m_settings->isEnabledPlugin(pluginId) || !m_dbusObserver->isDBusActivable(pluginId) || m_dbusObserver->isServiceRunning(pluginId)) {
+            continue;
+        }
+        const bool wasShown = m_shownItems.contains(pluginId);
+        const bool isShown = shownItems.contains(pluginId);
+        if (isShown && !wasShown) {
+            Q_EMIT plasmoidEnabled(pluginId);
+        } else if (!isShown && wasShown) {
+            Q_EMIT plasmoidStopped(pluginId);
+        }
+    }
+    m_shownItems = shownItems;
+}
+
 void PlasmoidRegistry::packageInstalled(const QString &pluginId)
 {
     qCDebug(SYSTEM_TRAY) << "New package installed" << pluginId;
@@ -133,7 +159,7 @@ void PlasmoidRegistry::registerPlugin(const KPluginMetaData &pluginMetaData)
         }
     }

-    if (m_settings->isEnabledPlugin(pluginId) && !m_dbusObserver->isDBusActivable(pluginId)) {
+    if (m_settings->isEnabledPlugin(pluginId) && (!m_dbusObserver->isDBusActivable(pluginId) || m_shownItems.contains(pluginId))) {
         Q_EMIT plasmoidEnabled(pluginId);
     }
 }
diff --git a/applets/systemtray/plasmoidregistry.h b/applets/systemtray/plasmoidregistry.h
index 7faae8721f..c4ae7eae1d 100644
--- a/applets/systemtray/plasmoidregistry.h
+++ b/applets/systemtray/plasmoidregistry.h
@@ -63,6 +63,7 @@ Q_SIGNALS:

 private Q_SLOTS:
     void onEnabledPluginsChanged(const QStringList &enabledPlugins, const QStringList &disabledPlugins);
+    void onConfigurationChanged();
     void packageInstalled(const QString &pluginId);
     void packageUninstalled(const QString &pluginId);

@@ -75,4 +76,5 @@ private:
     DBusServiceObserver *m_dbusObserver = nullptr;

     QMap<QString /*plugin id*/, KPluginMetaData> m_systrayApplets;
+    QStringList m_shownItems;
 };
